import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.LeafNode;
import org.junit.Test;
import org.mockito.Mockito;

public class TextNodeTest {

    @Test
    public void nodeName_NoText_ReturnsTagName() {
        LeafNode node = new LeafNode("div");
        TextNode textNode = (TextNode) node;
        assertEquals("div", textNode.nodeName());
    }

    @Test
    public void nodeName_WithText_ReturnsTextAsTagName() {
        String text = "test";
        LeafNode node = new LeafNode(text);
        TextNode textNode = (TextNode) node;
        assertEquals(text, textNode.nodeName());
    }

    @Test
    public void nodeName_ThrowsIllegalArgumentException() {
        assertThrows(IllegalArgumentException.class, () -> new TextNode(null));
    }

    @Test
    public void text_NoText_ReturnsEmptyString() {
        LeafNode node = new LeafNode();
        TextNode textNode = (TextNode) node;
        assertEquals("", textNode.text());
    }

    @Test
    public void text_WithText_ReturnsActualText() {
        String text = "test";
        LeafNode node = new LeafNode(text);
        TextNode textNode = (TextNode) node;
        assertEquals(text, textNode.text());
    }

    @Test
    public void text_ThrowsNullPointerException() {
        assertThrows(NullPointerException.class, () -> ((LeafNode) Mockito.mock(TextNode.class)).text());
    }

    @Test
    public void textAssign_NoText_ReturnsEmptyString() {
        LeafNode node = new LeafNode();
        TextNode textNode = (TextNode) node;
        textNode.text("");
        assertEquals("", textNode.text());
    }

    @Test
    public void textAssign_WithText_ReturnsActualText() {
        String text = "test";
        LeafNode node = new LeafNode(text);
        TextNode textNode = (TextNode) node;
        textNode.text("new text");
        assertEquals("new text", textNode.text());
    }

    @Test
    public void textAssign_ThrowsNullPointerException() {
        assertThrows(NullPointerException.class, () -> ((LeafNode) Mockito.mock(TextNode.class)).text(null));
    }

    @Test
    public void getWholeText_NoText_ReturnsEmptyString() {
        LeafNode node = new LeafNode();
        TextNode textNode = (TextNode) node;
        assertEquals("", textNode.getWholeText());
    }

    @Test
    public void getWholeText_WithText_ReturnsActualText() {
        String text = "test";
        LeafNode node = new LeafNode(text);
        TextNode textNode = (TextNode) node;
        assertEquals(text, textNode.getWholeText());
    }

    @Test
    public void isBlank_NoText_ReturnsTrue() {
        LeafNode node = new LeafNode();
        TextNode textNode = (TextNode) node;
        assertTrue(textNode.isBlank());
    }

    @Test
    public void isBlank_WithText_ReturnsFalse() {
        String text = "test";
        LeafNode node = new LeafNode(text);
        TextNode textNode = (TextNode) node;
        assertFalse(textNode.isBlank());
    }

    @Test
    public void splitText_NoOffset_ReturnsNull() {
        LeafNode node = new LeafNode();
        TextNode textNode = (TextNode) node;
        assertNull(textNode.splitText(0));
    }

    @Test
    public void splitText_WithOffset_ReturnsActualText() {
        String text = "test";
        LeafNode node = new LeafNode(text);
        TextNode textNode = (TextNode) node;
        assertEquals("te", textNode.splitText(1).text());
    }

    @Test
    public void clone_NoChange_ReturnsSameObject() {
        LeafNode node = new LeafNode();
        TextNode textNode = (TextNode) node;
        assertSame(textNode, textNode.clone());
    }

    @Test
    public void createFromEncoded_WithEncodedText_ReturnsActualText() {
        String encodedText = "test";
        assertEquals("test", TextNode.createFromEncoded(encodedText));
    }
}
